# owner: platform
"""Snapping spans to a step and labelling them."""

import unittest

from hourglass.rounding import label_rounded_spans
from hourglass.models import Span


class RoundingTests(unittest.TestCase):
    def test_snaps_both_ends_to_nearest_step(self):
        labels = label_rounded_spans([Span(542, 1037)], 15)
        self.assertEqual(labels, ["09:00-17:15 (8h 15m)"])

    def test_halves_round_up(self):
        labels = label_rounded_spans([Span(548, 600)], 15)
        self.assertEqual(labels, ["09:15-10:00 (0h 45m)"])

    def test_end_of_day_is_labelled_24_00(self):
        labels = label_rounded_spans([Span(1380, 1440)], 15)
        self.assertEqual(labels, ["23:00-24:00 (1h 0m)"])

    def test_one_label_per_span_in_order(self):
        spans = [Span(540, 720), Span(780, 1020)]
        labels = label_rounded_spans(spans, 30)
        self.assertEqual(
            labels,
            ["09:00-12:00 (3h 0m)", "13:00-17:00 (4h 0m)"]
        )

    def test_empty_list(self):
        self.assertEqual(label_rounded_spans([], 15), [])

    def test_span_that_collapses_is_an_error(self):
        with self.assertRaises(ValueError):
            label_rounded_spans([Span(541, 544)], 15)

    def test_bad_steps_are_rejected(self):
        spans = [Span(540, 600)]
        for step in (0, -15, 7, 120):
            with self.subTest(step=step):
                with self.assertRaises(ValueError):
                    label_rounded_spans(spans, step)
